export const POINTS_BRACKETS = ["4-8","9-12","13-16","17-20","21-24","25-28","29+"] as const;
export type PointsBracket = typeof POINTS_BRACKETS[number];

type RankTable = Record<string, number[]>;
type PointsMap = Record<string, RankTable>;

/** Returns the bracket index (0-6) for a given number of teams */
export function getBracketIndex(totalTeams: number): number {
  if (totalTeams <= 8)  return 0;
  if (totalTeams <= 12) return 1;
  if (totalTeams <= 16) return 2;
  if (totalTeams <= 20) return 3;
  if (totalTeams <= 24) return 4;
  if (totalTeams <= 28) return 5;
  return 6;
}

/** Returns points for a given category, rank and total number of teams. */
export function getPoints(category: string, rank: number, totalTeams: number): number {
  const cat = category.toUpperCase().replace(/[\s]/g, "");
  const table: RankTable | undefined = (POINTS_TABLE as PointsMap)[cat];
  if (!table) return 0;
  const bracketIdx = getBracketIndex(totalTeams);
  const exact = table[String(rank)];
  if (exact !== undefined) return exact[bracketIdx] ?? 0;
  const last = table["32+"];
  return last ? (last[bracketIdx] ?? 0) : 0;
}

